cd /Users/user/bench/runs/claude/t-jobs-base@s55/10/app && mkdir -p src/inngest src/app/api/inngest && cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED_EVENT = "notely/user.created";

export type UserCreatedData = {
  userId: string;
  email: string;
  name: string;
};

export const userReminder = inngest.createFunction(
  {
    id: "user-reminder",
    triggers: [{ event: USER_CREATED_EVENT }],
    // Up to 4 retries (5 attempts) with Inngest's exponential backoff.
    retries: 4,
  },
  async ({ event, step, logger }) => {
    const { userId, email, name } = event.data as UserCreatedData;

    await step.sleep("wait-10-minutes", "10m");

    // Each step is retried independently, so a failure here never restarts the sleep.
    await step.run("log-reminder", () => {
      logger.info(`Reminder: say hello to ${name} <${email}> (user ${userId}), signed up 10 minutes ago`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
cat > .env.example <<'EOF'
# Inngest (https://www.inngest.com). Not needed for local dev: run
#   npx inngest-cli@latest dev -u http://localhost:3000/api/inngest
# and set INNGEST_DEV=1 instead.
INNGEST_DEV=
INNGEST_EVENT_KEY=your-event-key
INNGEST_SIGNING_KEY=signkey-prod-your-signing-key
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { inngest } from "@/inngest/client";\nimport { USER_CREATED_EVENT } from "@/inngest/functions";\n\n'+s
s=s.replace('''export async function listUsers''','''export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedules the 10-minute reminder job; the id makes duplicate sends a no-op.
  await inngest.send({
    id: `user-created-${user.id}`,
    name: USER_CREATED_EVENT,
    data: { userId: user.id, email: user.email, name: user.name },
  });

  return user;
}

export async function listUsers''',1)
open(p,'w').write(s)
EOF
npx tsc --noEmit 2>&1 | head -20; npx eslint src 2>&1 | tail -10

